INSERT INTO `mail_messages` (`id`, `mail_message_type`, `mail_from_mail`, `mail_from_name`, `mail_subject`, `mail_body_html`, `mail_body_plain`, `mail_html`) VALUES
(1, 'password_forgotten_message', 'ludothek@ludothek.de', 'Saechsisches Spielezentrum', 'Neues Passwort fuer deinen Account auf Openbiblio', '<p>Hallo %FirstName% %LastName%,</p>\r\n<p>f&uuml;r deinen Account auf Openbiblio wurde nach einem neuen Passwort gefragt. Um ein neues Passwort zu vergeben, rufe innerhalb der n&auml;chsten %PwdForgottenCodeDuration% Stunden die folgende Website auf: %url_pwdcode%</p>\r\n<p>Sollte dir dein Passwort wieder eingefallen sein oder hast du dies nicht veranlasst, so ignoriere bitte diese E-Mail.</p>\r\n<p>Viele Gr&uuml;&szlig;e,<br>dein Team vom S&auml;chsischen Spielezentrum</p>', 'Hallo %FirstName% %LastName%,\r\n\r\nfür deinen Account auf Openbiblio wurde nach einem neuen Passwort gefragt. Um ein neues Passwort zu vergeben, rufe innerhalb der nächsten %PwdForgottenCodeDuration% Stunden die folgende Website auf: %url_pwdcode%\r\n\r\nSollte dir dein Passwort wieder eingefallen sein oder hast du dies nicht veranlasst, so ignoriere bitte diese E-Mail.\r\n\r\nViele Grüße,\r\ndein Team vom Sächsischen Spielezentrum', 1),
(2, 'welcome_message', 'ludothek@ludothek.de', 'Saechsisches Spielezentrum', 'Herzlich Willkommen auf Openbiblio', '<p>Hallo %FirstName% %LastName%,</p>\r\n<p>f&uuml;r deinen Account auf Openbiblio (dem Ausleihsystem der Ludothek) wurde nach einem neuen Passwort gefragt. Um ein neues Passwort zu vergeben, rufe innerhalb der n&auml;chsten %PwdForgottenCodeDuration% Stunden die folgende Website auf: %url_pwdcode%</p>\r\n<p>Wenn der Link schon abgelaufen sein sollte kannst du unter <a href=\"../opac/mbr_pwd_forget_form.php\">https://obiblio.ludothek.de/opac/mbr_pwd_forget_form.php</a> durch Eingabe von Benutzernummer und Mailadresse einen neuen Link anfordern.</p>\r\n<p>Viele Gr&uuml;&szlig;e,<br>dein Team vom S&auml;chsischen Spielezentrum</p>', 'Hallo %FirstName% %LastName%,\r\n\r\nfür deinen Account auf Openbiblio (dem Ausleihsystem der Ludothek) wurde nach einem neuen Passwort gefragt. Um ein neues Passwort zu vergeben, rufe innerhalb der nächsten %PwdForgottenCodeDuration% Stunden die folgende Website auf: %url_pwdcode%\r\n\r\nWenn der Link schon abgelaufen sein sollte kannst du unter https://obiblio.ludothek.de/opac/mbr_pwd_forget_form.php durch Eingabe von Benutzernummer und Mailadresse einen neuen Link anfordern.\r\n\r\nViele Grüße,\r\ndein Team vom Sächsischen Spielezentrum', 1);
